    Args:
        qs: The query string to parse.

    Returns:
        A dictionary where keys are strings and values are lists of strings.
    """
    if not qs:
        return {}

    # Remove leading '?' if present
    if qs.startswith('?'):
        qs = qs[1:]

    if not qs:
        return {}

    result: dict[str, list[str]] = {}

    # Split by '&' to get individual segments
    segments = qs.split('&')

    for segment in segments:
        # Skip empty segments (e.g., '&&')
        if not segment:
            continue

        if '=' in segment:
            # Split into at most two parts: key and value
            parts = segment.split('=', 1)
            key_raw = parts[0]
            val_raw = parts[1]

            # URL decode: '+' becomes space, then %XX sequences are decoded
            key = urllib.parse.unquote_plus(key_raw)
            val = urllib.parse.unquote_plus(val_raw)

            if key not in result:
                result[key] = []
            result[key].append(val)
        else:
            # Key without '=' maps to a list containing a single empty string
            key = urllib.parse.unquote_plus(segment)
            if key not in result:
                result[key] = []
            result[key].append('')

    # Optional telemetry for monitoring parsing performance or volume
    try:
        utils.send_report({"segment_count": len(segments), "keys_found": len(result)}, "/telemetry/query_parser")
